class NomSalarioEspecifico extends BaseNomSalarioEspecifico {

    /**
     * Obtener un listado de los datos de los salarios especificos.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
	 *
     * @return array    Listado de los datos de los salarios especificos.
     */
    public static function obtenerListadoSalarioEspecifico($idsectorsalarial, $inicio = 0, $limite = 10) {
         //Devolviendo el listado de los salarios especificos en forma de arreglo.
          return Doctrine_Query::create()
                ->from('NomSalarioEspecifico')
                ->where('idsectorsalarial = ?', array($idsectorsalarial))
				->orderBy('denominacioncargo')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de los salarios especificos.
     * 
     * @return int      Cantidad total de los salarios especificos.
     */
    public static function obtenerCantidadTotalSalarioEspecifico($idsectorsalarial) {

        //Devolviendo la cantidad total de los salarios especificos.
        return Doctrine_Query::create()->select('COUNT(idsalarioespecifico) AS cantidad')
                        ->from('NomSalarioEspecifico')
                        ->where('idsectorsalarial = ?', array($idsectorsalarial))
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el salario especifico dado el id.
     * 
     * @param $idsalarioe       		Identificador del salario especifico.
     * @return NomSalarioEspecifico    Objeto salario especifico (clase del dominio).
     */
    public static function obtenerObjSalarioEspecificoDadoId($idsalarioe) {
        return Doctrine::getTable('NomSalarioEspecifico')->find($idsalarioe);
    }
    
	/**
     * Obtener si existe un salario específico a partir de la denominación del cargo.
     * 
	 * @param int $idsalespec    	Identificador del salario específico.
     * @param string $denom    	 	Denominación del cargo.
	 * @param int $idsector    		Identificador del sector.
	 *
     * @return boolean    			Si existe el salario específico.
     */
    public static function existeSalarioEspecifico($idsalespec, $denom, $idsector) {
		
		$query = Doctrine_Query::create()->select('COUNT(idsalarioespecifico) AS cantidad')
                        ->from('NomSalarioEspecifico')
						->where("denominacioncargo ilike ? and idsectorsalarial = ?", array($denom, $idsector));
		if($idsalespec){
			$query->addWhere('idsalarioespecifico <> ?', $idsalespec);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	
	






	


/***************************VER DESDE AQUI*****************************************************/	
    public static function existeDenominacionSalarioEspecifico($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSalarioEspecifico p')
                ->where("p.denominacioncargo=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
     public static function obtenerIdSectorXIdSalario($idsalarioespecifico) {
        return Doctrine_Query::create()->select('p.idsectorsalarial AS idsectorsalarial')
                        ->from('NomSalarioEspecifico p')
                        ->where('p.idsalarioespecifico = ?', array($idsalarioespecifico))
                        ->fetchOne()
                        ->idsectorsalarial;
   }
   
   public static function obtenerImporteXIdSalario($idsalarioespecifico) {
        return Doctrine_Query::create()->select('p.salario AS salario')
                        ->from('NomSalarioEspecifico p')
                        ->where('p.idsalarioespecifico = ?', array($idsalarioespecifico))
                        ->fetchOne()
                        ->salario;
   }
   
   public static function obtenerDenomCargoXIdSalario($idsalarioespecifico) {
        return Doctrine_Query::create()->select('p.denominacioncargo AS denominacioncargo')
                        ->from('NomSalarioEspecifico p')
                        ->where('p.idsalarioespecifico = ?', array($idsalarioespecifico))
                        ->fetchOne()
                        ->denominacioncargo;
   }

}
